mapper.select:
select count(1) from person_face_search_log

		 and result = #{result} 
		 and valid_type = #{validType} 
      and received_time >= #{startTime} 
      and received_time <#{endTime}

select count(1) from person_face_match_log 

		 and result = #{result} 
      and received_time >= #{startTime} 
      and received_time <#{endTime}

select count(1) from person_finger_search_log

		 and result = #{result} 
      and received_time >= #{startTime} 
      and received_time <#{endTime}

select count(1) from person_iris_search_log

		 and result = #{result} 
      and received_time >= #{startTime} 
      and received_time <#{endTime}

select count(1) from person_faceiris_search_log 

		 and result = #{result} 
      and received_time >= #{startTime} 
      and received_time <#{endTime}

select device_code as deviceNo, max(device_name) as deviceName, count(1) as logNum from person_face_search_log  where device_code is not null and received_time >= #{startTime} and received_time <#{endTime} 

		and result = #{result} 

group by device_code order by logNum desc

select device_code as deviceNo, max(device_name) as deviceName, count(1) as logNum from person_face_match_log  where device_code is not null and received_time >= #{startTime} and received_time <#{endTime} 

		and result = #{result} 

group by device_code order by logNum desc

        select count(1) as logNum from person_face_match_log  where device_code in
		(select device_no from device_info where area_id = #{areaId} or area_id in ( select t.id from area_model t where find_in_set(#{areaId}, ancestors)))
		and received_time >= #{startTime} and received_time <#{endTime} 

       		and result = #{result}

        select count(1) as logNum from person_face_search_log  where device_code in
		(select device_no from device_info where area_id = #{areaId} or area_id in ( select t.id from area_model t where find_in_set(#{areaId}, ancestors)))
		and received_time >= #{startTime} and received_time <#{endTime} 

       		and result = #{result}

select device_sn as deviceNo, max(device_name) as deviceName, count(1) as logNum from person_faceiris_search_log  where device_sn is not null and received_time >= #{startTime} and received_time <#{endTime} 

		and result = #{result} 

group by device_sn order by logNum desc

select id, trade_num as tradeNum, pass_num as passNum, notpass_num as notpassNum, statistic_unit as statisticUnit,statistic_date as statisticDate, tenant_id as tenantId
from statistic_trade_log where statistic_unit = #{statisticUnit} and statistic_date = #{statisticDate}

	and tenant_id = #{tenantId}

select id, trade_num as tradeNum, pass_num as passNum, notpass_num as notpassNum, statistic_unit as statisticUnit,statistic_date as statisticDate, tenant_id as tenantId
from statistic_face_recog_log where statistic_unit = #{statisticUnit} and statistic_date = #{statisticDate}

	and tenant_id = #{tenantId}

select id, trade_num as tradeNum, pass_num as passNum, notpass_num as notpassNum, statistic_unit as statisticUnit,statistic_date as statisticDate, tenant_id as tenantId
from statistic_idcard_verify_log where statistic_unit = #{statisticUnit} and statistic_date = #{statisticDate}

	and tenant_id = #{tenantId}

select tenant_id as tenantId, count(1) as tradeNum from person_face_search_log where result = #{result} and received_time >= #{startTime} and received_time <#{endTime} 
 and valid_type = #{validType} 
group by tenant_id
